P=Path('curation/etymology-lab/indo-aryan-diversity-20260922');linked={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};edges=list(csv.DictReader(open('cldf/edges.csv')));linked.update(r['Child_ID'] for r in edges if r['Rank']=='1')
assert any(r['Child_ID']=='f_hv6ravplmmn4m' and r['Parent_ID']=='11625' and r['Rank']=='1' for r in edges)
