groups=[('aʦ','today','242','reflex','adya','Buddruss p26 item16 explicitly derives ac from *az from *aj, comparing the same z > c change elsewhere in Grangali. Turner242 adya gives regional aj/az today through MIA ajja. This source-explicit consonant development supports the existing today family without normalizing the installed affricate.'),('nun','today','7576','reflex','nūnam','Turner7576 explicitly lists Shumashti nun today under nūnam now, alongside Pashai nū and Gawri nūn. Buddruss p26 item16 confirms Shumashti nun as a distinct comparison, not a variant of Grangali ac.'),('byeλ','night','11625','reflex','vikāla','Buddruss p31 item97 gives Grangali byeλ, with another collection’s bel, beside Shumashti wyel and Gawri yel. Turner11625 vikāla evening gives Pashai vyāl/vel, Gawri yel and regional byäl forms. The b-y-l family and night sense support this assignment. The source lambda transcription is retained; unlike Shumashti, no specific loan route is established for this Grangali record.'),('vyel','night','f_hv6ravplmmn4m','borrowed','Pashai Kurangali vel','Turner11625 explicitly marks Pashai Kurangali vel as the donor of Shumashti wyel. Existing donor f_hv6ravplmmn4m has canonical Pas, dialect Kurangali and verified rank1 ancestry11625. Buddruss p31 item97 independently gives Shumashti wyel. Use this immediate donor rather than a direct reflex to vikāla.')]
a=[];lines=['# Grangali survey: today and night','','Four proposed records: three reflex links and one borrowing, under standing autonomous authorization.','','| # | Language form and meaning | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(f,g,parent,kind,label,ev) in enumerate(groups,1):
 hits=[r for r in rs if r['Form']==f and r['Gloss']==g];assert len(hits)==1,(f,hits)
 r=hits[0];cite='11625' if kind=='borrowed' else parent;a.append(dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},parent=parent,kind=kind,citation=r['Source']+';CDIAL['+cite+' and addenda]',evidence=ev))
 proposal='Borrowed from **'+label+'**' if kind=='borrowed' else '**'+label+'**, CDIAL **'+parent+'**'
 lines.append(f'| {i} | {r["Language_ID"]} **{f}** ‘{g}’ | {proposal} | {ev} |')
h=[dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},reason='The homepage6573 match is Zoller Gawri desāĩ, not a Turner Ningalam attestation. Buddruss identifies Ningalam desāī tomorrow while analyzing the separate Grangali phrase tasām dēsā day after tomorrow, but does not establish this reconstruction. Keep pending fuller comparative analysis; do not transfer the Gawri link solely from spelling.') for r in rs if r['Language_ID']=='Ning' and r['Gloss']=='tomorrow']
