sources={x['record']['Source'] for x in a+h};audit=[r for r in csv.DictReader(open('data/other/forms/raw_data/20260819-buddruss-grangali-audit.csv')) if r['Source'] in sources];assert all(r['Material_Error']=='no' for r in audit)
(P/'pass046-source-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
lines+=['','One Ningalam tomorrow record held; no compound phrase assigned. Source images directly inspected: existing render page-09/10/15, printed25/26/31. Research: homepage grangali-search011–012; full dictionary articles grangali-primary008–009. The existing Kurangali donor was verified in compiled forms and rank1 edges.','Validation: pending.']
